/** Native bank and real regional block restoration; pre-authorized repair intents are explicit fixtures. */
public final class SiegeTreasuryProbe extends JavaPlugin {
 static UUID id(String value){return UUID.nameUUIDFromBytes(("siege-treasury-052-"+value).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
 static final UUID T=id("town"),M=id("mayor");
 Path proof;String phase;int checks,withdrawals,deposits;World world;Location origin;Town town;TreasuryService treasury;NeverLandTownySiegesPlus owner;RaidRepairs repairs;RaidRepairsStore store;RaidStore ledger;RepairPlans.Plan plan;RaidRepairsStore.Job current;long firstPaid;final Map<UUID,Double> balances=new HashMap<>();
 interface Work{void run()throws Exception;}interface Receive<V>{void run(V value)throws Exception;}
 Object field(Object o,String name)throws Exception{var f=o.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(o);}
 void check(boolean result,String label)throws Exception{if(!result)throw new AssertionError(label);checks++;Files.writeString(proof.resolve(phase+"-checks.txt"),"PASS "+label+"\n",StandardOpenOption.CREATE,StandardOpenOption.APPEND);getLogger().info("CHECK "+label);}
 void fail(Throwable error){getLogger().log(java.util.logging.Level.SEVERE,"SIEGE TREASURY PROBE FAILED",error);try{Files.writeString(proof.resolve("failed.txt"),error.toString());}catch(Exception ignored){}Bukkit.getGlobalRegionScheduler().run(this,t->Bukkit.shutdown());}
 void later(long ticks,Work action){Bukkit.getRegionScheduler().runDelayed(this,origin,t->{if(!SuiteState.tryRun("Siege Treasury native",()->{try{action.run();}catch(Throwable error){fail(error);}}))later(1,action);},ticks);}
 <V>void after(CompletionStage<V> stage,Receive<V> action){stage.whenComplete((value,error)->later(1,()->{if(error!=null)throw new IllegalStateException(error);action.run(value);}));}
 void until(BooleanSupplier condition,Work next,int left)throws Exception{if(condition.getAsBoolean()){next.run();return;}if(left<=0)throw new AssertionError("Siege condition timed out");later(1,()->until(condition,next,left-1));}
 @Override public void onEnable(){if(!Files.isRegularFile(Path.of("ALLOW_DISPOSABLE_RAID_PROBE"))||!"127.0.0.1".equals(getServer().getIp())){Bukkit.getPluginManager().disablePlugin(this);return;}proof=getDataFolder().toPath();Bukkit.getGlobalRegionScheduler().runDelayed(this,t->{try{Files.createDirectories(proof);phase=Files.exists(proof.resolve("first-passed.txt"))?"restart":"first";world=Bukkit.getWorlds().getFirst();origin=new Location(world,8,140,8);world.getChunkAtAsync(0,0).whenComplete((chunk,error)->{if(error!=null)fail(error);else later(2,this::setup);});}catch(Throwable error){fail(error);}},40);}
 double balance(){return town.getAccount().getHoldingBalance(true);}long cents(){return Math.round(balance()*100);}
 void setup()throws Exception{
  world.addPluginChunkTicket(0,0,this);
  owner=(NeverLandTownySiegesPlus)Bukkit.getPluginManager().getPlugin("NeverLandTownySiegesPlus");repairs=owner.repairs();store=repairs.store();ledger=owner.raids().store();treasury=(TreasuryService)Bukkit.getServicesManager().load(TownyTreasuryApi.class);check(repairs!=null&&treasury!=null&&ledger.healthy(),"actual repair journal and Treasury services enabled");
  var builds=Bukkit.getPluginManager().getPlugin("NeverLandTownyBuilds");var construction=field(builds,"construction");construction.getClass().getMethod("stop").invoke(construction);((BukkitTask)field(owner,"lootTask")).cancel();
  if(phase.equals("first")){var u=TownyUniverse.getInstance();u.newTownInternal("RepairTreasuryCity",T);town=TownyAPI.getInstance().getTown(T);var r=u.getDataSource().newResident("RepairTreasuryMayor",M);r.setTown(town);town.setMayor(r);r.save();var home=new TownBlock(0,0,u.getWorld(world.getName()));u.addTownBlock(home);home.setTown(town);town.setHomeBlock(home);town.setSpawn(origin);home.save();town.save();var data=(DataStore)field(builds,"dataStore");data.town(T).setConstructionSite(new ConstructionSite("town_hall",world.getUID(),1,140,1,BlockFace.NORTH,1,1,2,false,ConstructionSite.CURRENT_ARCHITECTURE_VERSION));data.town(T).setLevel("town_hall",1);data.markDirty();data.saveOrThrow();}else{town=TownyAPI.getInstance().getTown(T);SuiteState.freeze(owner.getName());}
  plan=new RepairPlans().plan(T,"town_hall");check(!plan.cells().isEmpty()&&!plan.active(),"real completed Builds plan supplies frozen repair geometry and level price");bank();sync(300);
 }
 void sync(int left)throws Exception{try{treasury.sync(town);}catch(IllegalStateException busy){if(left<=0)throw busy;later(1,()->sync(left-1));return;}if(phase.equals("first"))create(0,this::holdFirst);else resume();}
 void create(int index,Work next)throws Exception{
  var cell=plan.cells().stream().filter(c->c.key().x()>>4==0&&c.key().z()>>4==0&&c.top().isEmpty()).skip(index).findFirst().orElseThrow();double hp=owner.raids().settings().hp(cell.hpMaterial());world.getBlockAt(cell.key().x(),cell.key().y(),cell.key().z()).setType(Material.AIR,false);
  after(ledger.damage(UUID.randomUUID(),M.toString(),id("attacker"),T,System.currentTimeMillis(),1800,List.of(new RaidStore.Hit(cell.key(),T,cell.material(),index+1,hp,hp,"town_hall"))),hits->after(ledger.finish(hits.get(0),true),nothing->after(new BuildingDamageStore(ledger).list(T,"town_hall"),rows->{
   var damage=rows.stream().filter(r->r.key().equals(cell.key())).findFirst().orElseThrow();double maximum=plan.cells().stream().mapToDouble(c->owner.raids().settings().hp(c.hpMaterial())).sum();long cost=RepairRules.cost(plan.price(),hp,maximum);check(cost>0,"positive repair charge derived from real building price and damaged share");
   var cells=List.of(new RaidRepairsStore.Cell(cell,damage.version(),damage.remaining(),damage.maximum(),true));after(store.create(M,plan,maximum,hp,cost,cents(),cells,true),job->{current=job;next.run();});
  })));
 }
 void fund()throws Exception{if(!Set.of("TREASURY_PENDING","TREASURY_REVIEW").contains(current.state()))return;var method=RaidRepairs.class.getDeclaredMethod("fund",RaidRepairsStore.Job.class);method.setAccessible(true);method.invoke(repairs,current);}
 void prepareHeld(int left,Work next)throws Exception{SuiteState.thaw(owner.getName());try{fund();}finally{SuiteState.freeze(owner.getName());}String state=(String)treasury.debitStatus(current.id()).get("status");if(state.equals("PREPARED")){next.run();return;}if(!state.equals("ABSENT")||left<=0)throw new AssertionError("Expected pending repair before bank, got "+state);later(1,()->prepareHeld(left-1,next));}
 void holdFirst()throws Exception{
  check(current.state().equals("TREASURY_PENDING")&&current.treasury()&&withdrawals==0,"repair intent durable before bank and world effects");var manager=Bukkit.getServicesManager();manager.unregister(TownyTreasuryApi.class,treasury);check(new RepairBank().poll(current,true)==RepairTreasury.Outcome.WAITING&&withdrawals==0,"missing installed Treasury API holds repair without direct bank fallback");manager.register(TownyTreasuryApi.class,treasury,Bukkit.getPluginManager().getPlugin("NeverLandTownyTreasuryPlus"),ServicePriority.Normal);
  boolean refused=false;try{new RepairBank().withdraw(current);}catch(IllegalStateException expected){refused=true;}check(refused&&withdrawals==0,"legacy synchronous debit cannot bypass installed Treasury");prepareHeld(300,()->{check(withdrawals==0&&air(current),"owner pause preserves pending debit and leaves damaged block untouched");firstPaid=current.cents();SuiteState.thaw(owner.getName());settle(300,this::paidFirst);});
 }
 boolean air(RaidRepairsStore.Job job){var k=job.cells().getFirst().block().key();return world.getBlockAt(k.x(),k.y(),k.z()).getType().isAir();}
 void settle(int left,Work next)throws Exception{fund();repairs.pulse();after(store.get(current.id()),saved->{current=saved;if(saved.state().equals("DONE")){next.run();return;}if(left<=0)throw new AssertionError("Repair not completed: "+saved.state()+" "+saved.note()+"; chunk="+world.isChunkLoaded(0,0)+"; working="+field(repairs,"working")+"; managed="+owner.raids().managed(T));later(1,()->settle(left-1,next));});}
 void paidFirst()throws Exception{check(withdrawals==1&&cents()==10000000-firstPaid&&!air(current),"one confirmed debit precedes real regional block restoration");check(treasury.debitStatus(current.id()).get("status").equals("PAID"),"original exact Treasury receipt preserved after completed repair");repairs.pulse();check(withdrawals==1,"completed repair cannot charge again");create(1,()->prepareHeld(300,()->{check(withdrawals==1&&air(current),"second repair remains unpaid and physically damaged for full restart");var values=new Properties();values.setProperty("pending",current.id().toString());values.setProperty("firstPaid",Long.toString(firstPaid));try(var out=Files.newOutputStream(proof.resolve("fixture.properties"))){values.store(out,"Explicit accepted repair intent");}finish();}));}
 void resume()throws Exception{var values=new Properties();try(var in=Files.newInputStream(proof.resolve("fixture.properties"))){values.load(in);}firstPaid=Long.parseLong(values.getProperty("firstPaid"));UUID pending=UUID.fromString(values.getProperty("pending"));after(store.get(pending),saved->{current=saved;check(saved.treasury()&&saved.state().equals("TREASURY_PENDING")&&saved.actor().equals(M),"restart restores original ID, actor, route, terms and pending damage");check(withdrawals==0&&cents()==10000000-firstPaid&&air(saved),"restart has neither repeated payment nor free block repair");check(treasury.debitStatus(pending).get("status").equals("PREPARED"),"Treasury keeps exact pending debit while repair owner is paused");SuiteState.thaw(owner.getName());settle(300,()->{check(withdrawals==1&&cents()==10000000-firstPaid-current.cents()&&!air(current),"saved repair settles once and restores its block after full JVM restart");repairs.pulse();check(withdrawals==1,"restored completed job remains replay-safe");finish();});});}
 void finish()throws Exception{var values=new Properties();balances.forEach((k,v)->values.setProperty(k.toString(),v.toString()));try(var out=Files.newOutputStream(proof.resolve("bank.properties"))){values.store(out,"Explicit persistent deterministic bank fixture");}TownySettings.setProperty("economy.using_economy",false);TownyUniverse.getInstance().getDataSource().saveAll();Files.writeString(proof.resolve(phase+"-passed.txt"),"PASS "+checks+" checks; actual Folia/Towny/Builds/Sieges/Treasury, native regional block repair, durable intents and full restart; deterministic economy adapter and pre-authorized damage/intent fixtures; no live Vault or network player claimed\n");Bukkit.getGlobalRegionScheduler().run(this,t->Bukkit.shutdown());}
 void bank()throws Exception{if(Files.exists(proof.resolve("bank.properties"))){var p=new Properties();try(var in=Files.newInputStream(proof.resolve("bank.properties"))){p.load(in);}p.forEach((k,v)->balances.put(UUID.fromString(k.toString()),Double.parseDouble(v.toString())));}
  var adapter=(EconomyAdapter)Proxy.newProxyInstance(EconomyAdapter.class.getClassLoader(),new Class<?>[]{EconomyAdapter.class},(p,m,a)->{Account account=a!=null&&a.length>0&&a[0] instanceof Account x?x:null;UUID id=account==null?null:account.getUUID();double old=balances.getOrDefault(id,0.0);return switch(m.getName()){case "name","toString"->"Repair deterministic native bank fixture";case "hasAccount"->true;case "getBalance"->old;case "newAccount","deleteAccount"->null;case "getFormattedBalance"->String.valueOf(a[0]);case "setBalance"->{balances.put(id,(Double)a[1]);yield true;}case "renameAccount"->true;case "add","subtract"->{double n=(Double)a[1];boolean add=m.getName().equals("add");if(!add&&old<n)yield false;balances.put(id,old+(add?n:-n));if(add)deposits++;else withdrawals++;yield true;}default->throw new UnsupportedOperationException(m.getName());};});
  var f=sun.misc.Unsafe.class.getDeclaredField("theUnsafe");f.setAccessible(true);var unsafe=(sun.misc.Unsafe)f.get(null);EconomyProvider provider=(EconomyProvider)unsafe.allocateInstance(Class.forName("com.palmergames.bukkit.towny.object.economy.provider.ReserveEconomyProvider",false,Towny.class.getClassLoader()));for(var e:Map.of("economy",adapter,"provider",provider).entrySet()){var x=TownyEconomyHandler.class.getDeclaredField(e.getKey());x.setAccessible(true);x.set(null,e.getValue());}TownySettings.setProperty("economy.using_economy",true);if(phase.equals("first"))town.getAccount().deposit(100000,"disposable repair seed");deposits=withdrawals=0;
 }
}
